#!/usr/bin/env bash
# The default-options test. features.yml runs only the scenarios
# (--skip-autogenerated): the default flavor is official, which has no
# default pins, so installing it with its defaults fails by design and this
# script is not reached there. It is kept for a local run that supplies a
# pin through the image (for example `devcontainer features test -f
# cli-keycloak -i <image with CLI_KEYCLOAK_* ENV>`).
set -e

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=keycloak-checks.sh
source "$(dirname "$0")/keycloak-checks.sh"

expect_official "${CLI_KEYCLOAK_VERSION:-}"

reportResults
